// Generated by Cypress Author on 2026-11-26.
// Décrire le scénario de persistance du panier après reconnexion.
describe('Swag Labs cart persistence', () => {
    // Préparer une session utilisateur avant le scénario.
    beforeEach(() => {
        // Se connecter avec la commande partagée.
        cy.login();
        // Ajouter le Sauce Labs Backpack depuis l'inventaire.
        cy.get('[data-test="add-to-cart-sauce-labs-backpack"]').click();
        // Ajouter le Sauce Labs Bike Light depuis l'inventaire.
        cy.get('[data-test="add-to-cart-sauce-labs-bike-light"]').click();
        // Ouvrir la page du panier.
        cy.get('[data-test="shopping-cart-link"]').click();
        // Vérifier que la page du panier est affichée.
        cy.location('pathname').should('eq', '/cart.html');
        // Vérifier que le badge conserve le nombre des deux articles.
        cy.get('.cart_item').should('have.length', 2);
    });

    // Fermer la session après le scénario.
    afterEach(() => {
        // Se déconnecter avec la commande partagée.
        cy.logout();
    });

    // Déclarer le scénario de persistance après déconnexion et reconnexion à compléter.
    it('conserve le panier après déconnexion et reconnexion', () => {
        // Faire la déconnexion sur la session
        cy.get('#react-burger-menu-btn').should('be.visible').click({force: true});
        cy.get('#logout_sidebar_link').should('be.visible').click();
        // vérifier que Le navigateur est sur la page login
        cy.get('[data-test="login-button"]').should('be.visible');
        // Se reconnecter autre fois
        cy.get('[data-test="username"]').type("standard_user");
        cy.get('[data-test="password"]').type("secret_sauce");
        cy.get('[data-test="login-button"]').click();
        // Ouvrir le panier
        cy.get('[data-test="shopping-cart-link"]').click();
        // Le persistance des produits déjà ajoutés avant la déconnexion
        // Vérifier que le Sauce Labs Backpack est toujours dans le panier.
        cy.contains('[data-test="inventory-item-name"]', 'Sauce Labs Backpack').should('exist').and('be.visible');
        // Vérifier que le Sauce Labs Bike Light est toujours dans le panier.
        cy.contains('[data-test="inventory-item-name"]', 'Sauce Labs Bike Light').should('exist').and('be.visible');
    });
});
